// Search customers by name, email, or phone
// ============================================
router.get('/get-all-by-query', async (req, res) => {
    try {
        const { query } = req.query;

        // ✅ Validate query parameter
        if (!query || query.trim().length === 0) {
            return res.status(400).json({
                success: false,
                message: 'Search query is required'
            });
        }

        const searchTerm = `%${query.trim()}%`;

        // ✅ Execute query
        const customers = await Customer.findAll({
            where: {
                [Op.or]: [
                    { name: { [Op.like]: searchTerm } },
                    { email: { [Op.like]: searchTerm } },
                    { phone: { [Op.like]: searchTerm } },
                    // FIXED: Using '$record.workbook$' matches the alias generated by Sequelize ('record')
                    { '$record.workbook$': { [Op.like]: searchTerm } }
                ]
            },
            include: [
                {
                    model: CustomerRecord,
                    as: 'record', // Uses alias 'record' as defined in your model associations
                    required: false,
                    attributes: ['id', 'workbook']
                }
            ],
            attributes: {
                exclude: ['password']
            },
            order: [
                ['name', 'ASC'],
                ['id', 'ASC']
            ],
            limit: 10,
            subQuery: false
        });

        // ✅ Return matching list
        return res.json({
            success: true,
            data: customers
        });

    } catch (error) {
        console.error('Error fetching customers by query:', error);
        return res.status(500).json({
            success: false,
            message: 'Failed to fetch customers',
            error: process.env.NODE_ENV === 'development' ? error.message : undefined
        });
    }
});
// ✅ Get all customers
router.get('/all', authenticate, async (req, res) => {
    try {
        const {
            search,
            status,
            preferred_contact,
            sortBy,
            sortOrder,
            page,
            limit
        } = req.query;

        // Build where clause
        const where = {};
        if (status) {
            where.status = status;
        }
        if (preferred_contact) {
            where.preferred_contact = preferred_contact;
        }

        // Search functionality
        if (search) {
            where[Op.or] = [
                { name: { [Op.like]: `%${search}%` } },
                { email: { [Op.like]: `%${search}%` } },
                { phone: { [Op.like]: `%${search}%` } }
            ];
        }

        // Pagination
        const pageNum = parseInt(page) || 1;
        const limitNum = parseInt(limit) || 10;
        const offset = (pageNum - 1) * limitNum;

        // Sorting
        const order = [];
        if (sortBy) {
            const sortDirection = sortOrder === 'desc' ? 'DESC' : 'ASC';
            order.push([sortBy, sortDirection]);
        } else {
            order.push(['created_at', 'DESC']);
        }

        const { count, rows } = await Customer.findAndCountAll({
            where,
            order,
            limit: limitNum,
            offset
        });

        res.json({
            success: true,
            data: rows,
            pagination: {
                total: count,
                page: pageNum,
                limit: limitNum,
                totalPages: Math.ceil(count / limitNum)
            }
        });

    } catch (error) {
        console.error('Error fetching customers:', error);
        res.status(500).json({
            success: false,
            message: 'Failed to fetch customers'
        });
    }
});

// ✅ Get customer by ID
router.get('/', authenticate, async (req, res) => {
    try {
        const { id } = req.query;
        const result = await Customer.findByPk(id, {
            include: [{ model: CustomerRecord, as: 'record' }]
        });

        if (!result) {
            return res.fail('Customer not found', 404)
        }
        return res.success(result, 'Customer fetched successfully', 200)

    } catch (error) {
        console.error('Error fetching customer:', error);
        res.fail('Failed to fetch customer', 500)
    }
});

// ✅ Delete customer (soft delete or hard delete)
router.delete('/:id', authenticate, async (req, res) => {
    try {
        const { id } = req.params;
        const { permanent } = req.query;

        const customer = await Customer.findByPk(id);

        if (!customer) {
            return res.status(404).json({
                success: false,
                message: 'Customer not found'
            });
        }

        if (permanent === 'true') {
            // Hard delete
            await customer.destroy();
            res.json({
                success: true,
                message: 'Customer permanently deleted'
            });
        } else {
            // Soft delete - set status to archived
            await customer.update({ status: 'archived' });
            res.json({
                success: true,
                message: 'Customer archived successfully'
            });
        }

    } catch (error) {
        console.error('Error deleting customer:', error);
        res.status(500).json({
            success: false,
            message: 'Failed to delete customer'
        });
    }
});

